import json
from datetime import datetime, timezone, timedelta
from collection import REPO, clean, date_label, field, number, prepare

RAW=REPO.parent/'research/2026-09-07-earthquakes'
NOAA=REPO.parent/'research/2026-09-07-tsunamis/earthquakes.json'
sources=[
    dict(id='noaa',label='NOAA historical impacts',name='NCEI/WDS Global Significant Earthquake Database',provider='NOAA National Centers for Environmental Information / World Data Service',color='#1e3a5f',citation='NCEI / World Data Service: Global Significant Earthquake Database. NOAA National Centers for Environmental Information. DOI: 10.7289/V5TD9V7K. Accessed 7 September 2026.',license='NOAA public data; cite NCEI/WDS and original references. Third-party source material retains its own rights.',url='https://www.ncei.noaa.gov/products/natural-hazards/tsunamis-earthquakes-volcanoes/earthquakes',note='Complete published NOAA significant-earthquake layer. Its inclusion criteria include deaths, substantial damage, magnitude at least 7.5, intensity X or greater, or an associated tsunami. Historical descriptions and impact counts vary in certainty and completeness.'),
    dict(id='usgs',label='USGS ComCat',name='USGS ANSS Comprehensive Earthquake Catalog — significance ≥600',provider='U.S. Geological Survey / ANSS and contributing seismic networks',color='#9a642b',citation='U.S. Geological Survey. ANSS Comprehensive Earthquake Catalog (ComCat), FDSN event service. Earthquakes from 1900-01-01 through 2026-09-07 00:00 UTC with significance ≥600. Accessed 7 September 2026. https://earthquake.usgs.gov/fdsnws/event/1/',license='U.S. federal public data. Credit USGS, ANSS and contributing networks. Original event IDs, links and attributes are retained.',url='https://earthquake.usgs.gov/fdsnws/event/1/',note='Complete acquired query for the explicit period and significance threshold, downloaded in decade intervals. USGS significance combines magnitude, felt reports and PAGER alert information; it does not mean measured physical damage. PAGER is an automated estimate. USGS and NOAA can describe the same earthquake and remain separate source records without a shared identifier.')
]
rows,details=[],{}
raw=json.loads(NOAA.read_text(encoding='utf-8'))
country_names={clean(f['attributes'].get('COUNTRY')).upper() for f in raw['features']}
for feature in raw['features']:
    a=feature['attributes'];native=str(a['ID']);rid='noaa-earthquake-'+native
    magnitude=number(a.get('EQ_MAGNITUDE'))
    scales=[scale for scale,key in [('Mw','EQ_MAG_MW'),('Ms','EQ_MAG_MS'),('mb','EQ_MAG_MB'),('Ml','EQ_MAG_ML'),('Mfa','EQ_MAG_MFA'),('Unknown','EQ_MAG_UNK')] if magnitude is not None and number(a.get(key)) == magnitude]
    r=dict(id=rid,nativeId=native,name=clean(a.get('LOCATION_NAME')).title() or ('Earthquake '+native),country=clean(a.get('COUNTRY')).title(),countryBasis='NOAA country field',source='noaa',kind='Historical impact record',eventId=rid,date=date_label(a.get('YEAR'),a.get('MONTH'),a.get('DAY')),year=number(a.get('YEAR')),lat=number(a.get('LATITUDE')),lon=number(a.get('LONGITUDE')),magnitude=magnitude,magnitudeType=scales[0] if len(scales)==1 else 'See original magnitude fields',momentMagnitude=number(a.get('EQ_MAG_MW')),depth=number(a.get('EQ_DEPTH')),historicalIntensity=number(a.get('INTENSITY')),deaths=number(a.get('DEATHS'),True),injuries=number(a.get('INJURIES'),True),housesDestroyed=number(a.get('HOUSES_DESTROYED'),True),housesDamaged=number(a.get('HOUSES_DAMAGED'),True),damageMillions=number(a.get('DAMAGE_MILLIONS_DOLLARS'),True),tsunamiAssociation='NOAA association flag' if a.get('FLAG_TSUNAMI') else None)
    details[rid]=dict(attributes=a,geometry={'type':'Point','coordinates':[r['lon'],r['lat']]} if r['lat'] is not None and r['lon'] is not None else None,url=a.get('URL'),note=clean(a.get('COMMENTS')),geometryNote='NOAA source earthquake location; uncertainty varies by period and original evidence. The pin is not an affected-area footprint.')
    rows.append(r)
usgs={}
for year in range(1900,2027,10):
    payload=json.loads((RAW/f'usgs-{year}.json').read_text(encoding='utf-8'))
    if len(payload.get('features',[])) >= 20000:
        raise RuntimeError('A decade reaches the provider limit; subdivide before publication')
    for f in payload['features']:
        usgs[f['id']]=f
for native,feature in sorted(usgs.items(),key=lambda item:(item[1]['properties']['time'],item[0])):
    a=feature['properties'];lon,lat,depth=feature['geometry']['coordinates'];rid='usgs-'+native
    when=datetime(1970,1,1,tzinfo=timezone.utc)+timedelta(milliseconds=a['time'])
    place=clean(a.get('place'));tail=place.rsplit(',',1)[-1].strip().upper()
    country=tail.title() if ',' in place and tail in country_names else None
    if tail in {'CA','CALIFORNIA','ALASKA','HAWAII','NEVADA','MONTANA','WASHINGTON','UTAH','OKLAHOMA','TEXAS','NEW MEXICO','ARIZONA','OREGON','IDAHO','WYOMING','TENNESSEE','KANSAS','OHIO','NEW YORK','VIRGINIA','MAINE','MASSACHUSETTS','PENNSYLVANIA','NEW JERSEY'}:country='United States'
    r=dict(id=rid,nativeId=native,name=place or ('Earthquake '+native),country=country,countryBasis='Explicit country/state in USGS place label' if country else 'Country not supplied',source='usgs',kind='Instrumental event record',eventId=rid,date=when.isoformat().replace('+00:00','Z'),year=when.year,lat=lat,lon=lon,depth=depth,magnitude=number(a.get('mag')),magnitudeType=clean(a.get('magType')),momentMagnitude=number(a.get('mag')) if str(a.get('magType','')).lower().startswith('mw') else None,shakemapIntensity=number(a.get('mmi')),feltIntensity=number(a.get('cdi')),feltResponses=number(a.get('felt'),True),significance=number(a.get('sig'),True),pagerAlert=clean(a.get('alert')),reviewStatus=clean(a.get('status')),network=clean(a.get('net')),tsunamiAssociation='USGS tsunami-link flag (not confirmation)' if a.get('tsunami') else None)
    details[rid]=dict(attributes={**a,'source_event_id':native,'source_geometry':feature['geometry']},geometry={'type':'Point','coordinates':[lon,lat]},url=a.get('url'),note='USGS preferred event solution at acquisition. PAGER alert levels estimate potential impacts and do not report confirmed casualties. Felt responses are reports, not an affected-population count. The USGS tsunami flag indicates a link/product association; it does not establish that a tsunami occurred.',geometryNote='USGS epicentral longitude and latitude. Source GeoJSON encodes depth in kilometres in the third coordinate; the downloadable display geometry uses two coordinates and retains depth as an attribute, avoiding confusion with GeoJSON altitude.')
    rows.append(r)

config=dict(slug='earthquakes',title='Earthquakes',homepageTitle='Earthquakes & Impacts',singular='earthquake',article='an',sources=sources,
    intro='Explore significant earthquakes, documented historical impacts and instrumental event records from NOAA and USGS.',
    coverage='NOAA global historical significant earthquakes and USGS significance ≥600 events since 1900, through 7 September 2026 00:00 UTC. A research snapshot, not a real-time alert service.',
    countNote='Counts describe source records. NOAA and USGS inclusion criteria differ, and their catalogues can describe the same earthquake. USGS decade-query overlaps are reconciled only by exact provider event ID. Cross-provider records are not merged merely by proximity.',
    statisticsNote='Statistics cover all source records matching the filters. Provider selection thresholds and historical reporting mean these are not global earthquake-rate estimates. Prefer the moment-magnitude variable when comparing event size; preferred magnitudes can use different scales. Unknown impact counts remain missing. Historical MMI, ShakeMap estimates and felt intensities are separate variables. Negative source years denote BCE.',
    measurementNote='NOAA earthquake-attributed impact fields are displayed separately from the source’s combined disaster totals, which remain in original attributes. PAGER is a modelled potential-impact alert, not confirmed damage. Financial amounts are historical source estimates in millions of U.S. dollars; they are not inflation-adjusted. Do not sum overlapping source records.',
    methods=f'All {len(raw["features"]):,} NOAA layer records and {len(usgs):,} distinct USGS provider IDs from the acquired significance query are included. Partial NOAA dates remain partial. Original attributes and provenance are retained; no casualty values are inferred from qualitative ranges. USGS country labels are populated only where an explicit country/state is recognized in the supplied place text; offshore and unresolved labels remain unknown. Reported country and place-derived labels are distinguished by a separate field.',
    definition='An earthquake occurs when rock suddenly slips along a fault, releasing energy as seismic waves. The underground starting point is the hypocentre; its projection on the surface is the epicentre. Shaking and impacts vary across the surrounding area.',
    definitionUrl='https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes',definitionSource='USGS — The Science of Earthquakes',
    diagramAlt='A cross-section showing a fault, an underground hypocentre, its surface epicentre and outward travelling seismic waves.',diagramCaption='Earthquake source and surface location. A catalogue pin locates the epicentre, not the full area of shaking. Schematic; not to scale.',
    diagram='''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="700" viewBox="0 0 1200 700"><rect width="1200" height="700" fill="#f5f4ef"/><path d="M0 240H1200V700H0Z" fill="#d0c5b1"/><path d="M740 240L400 700" fill="none" stroke="#725746" stroke-width="9"/><g fill="none" stroke="#9a642b" stroke-width="3"><circle cx="570" cy="470" r="65"/><circle cx="570" cy="470" r="120"/><circle cx="570" cy="470" r="190"/></g><path d="M570 240V470" stroke="#1e3a5f" stroke-width="3" stroke-dasharray="10 10"/><circle cx="570" cy="470" r="12" fill="#1e3a5f"/><circle cx="570" cy="240" r="9" fill="#1e3a5f"/><path d="M590 470H930M735 285H960" stroke="#394b54" stroke-width="2"/><g font-family="Georgia,serif" fill="#172735"><text x="70" y="90" font-size="50">Locating an earthquake</text><text x="485" y="190" font-size="30">Epicentre</text><text x="950" y="480" font-size="29">Hypocentre</text><text x="980" y="295" font-size="29">Fault</text><text x="110" y="535" font-size="29">Seismic waves</text></g></svg>''',
    fields=[field('momentMagnitude','Moment magnitude','Mw-family magnitudes only. NOAA Mw and USGS mw, mww, mwc and related moment-magnitude types are included.',scale='linear'),field('magnitude','Preferred source magnitude','Provider preferred magnitude. Scales vary; use the magnitude-type filter or the moment-magnitude variable for clearer comparison.',scale='linear'),field('depth','Hypocentral depth','Provider-reported depth in kilometres. Negative USGS depths can occur for shallow events and are retained. Not a surface elevation.','km',scale='linear'),field('historicalIntensity','Historical maximum MMI','NOAA maximum Modified Mercalli Intensity, an ordinal historical assessment. Kept separate from ShakeMap and felt-intensity estimates.',scale='linear'),field('shakemapIntensity','ShakeMap maximum MMI','USGS ShakeMap estimated maximum Modified Mercalli Intensity. A modelled shaking estimate, not measured loss.',scale='linear'),field('feltIntensity','Felt-report maximum intensity','USGS DYFI maximum community-determined intensity. Its coverage depends on voluntary reports.',scale='linear'),field('feltResponses','Felt responses','Number of USGS Did You Feel It responses, not people affected.','responses'),field('deaths','Reported earthquake deaths','NOAA numerical earthquake-attributed death count. Qualitative ranges and combined disaster totals remain in original attributes. Do not add overlapping catalogues.','people'),field('injuries','Reported earthquake injuries','NOAA numerical earthquake-attributed injury counts. Unknown values remain missing.','people'),field('housesDestroyed','Houses destroyed','NOAA numerical reported count; source completeness varies.','houses'),field('housesDamaged','Houses damaged','NOAA numerical reported count, distinct from destroyed houses.','houses'),field('damageMillions','Reported historical damage','Source-reported earthquake damage in millions of U.S. dollars; historical currency values are not inflation adjusted.','million USD'),field('year','Reported year','Provider year. Negative years denote BCE. Source coverage and selection change through time.',scale='linear',group='Chronology'),field('country','Country, where supplied','NOAA country or a recognized country/state explicitly named in the USGS place label; unresolved cases remain missing.',categorical=True,group='Location'),field('source','Source collection','NOAA historical impacts or the USGS significance-filtered catalogue.',categorical=True),field('kind','Record type','Historical impact account or instrumental preferred event solution.',categorical=True),field('magnitudeType','Magnitude type','Source magnitude scale. Ambiguous NOAA preferred magnitude matches remain labelled for inspection.',categorical=True),field('pagerAlert','PAGER potential-impact alert','USGS automated estimate of possible impacts. This is not confirmed damage or a present alert.',categorical=True),field('reviewStatus','USGS review status','Provider status such as automatic or reviewed; not an independent NKUA assessment.',categorical=True),field('tsunamiAssociation','Tsunami source flag','NOAA association flag or USGS link flag. The latter does not confirm tsunami occurrence.',categorical=True),field('countryBasis','Country attribution basis','Distinguishes a provider country field from a country/state explicitly recognized in a source place label.',categorical=True)])
prepare(config,rows,details)
